("Components", "ToggleGroup", "Disabled", "components-togglegroup--disabled", .centered),
  ]
  static func apply(_ groups: [StoryGroup]) -> [StoryGroup] {
    var result = groups
    for entry in entries {
      let key = "\(entry.group)/\(entry.page)/\(entry.name)"
      let generated = Story(entry.name, layout: entry.layout, sourceId: entry.id) { content(key)! }
      if !result.contains(where: { $0.name == entry.group }) {
        result.append(StoryGroup(entry.group, pages: []))
      }
      let g = result.firstIndex { $0.name == entry.group }!
      var pages = result[g].pages
      if !pages.contains(where: { $0.name == entry.page }) {
        pages.append(StoryPage(entry.page, stories: []))
      }
      let p = pages.firstIndex { $0.name == entry.page }!
      var stories = pages[p].stories
      if let i = stories.firstIndex(where: {
        ($0.sourceId ?? storyId(group: entry.group, page: entry.page, story: $0.name)) == entry.id ||
        $0.name.lowercased() == entry.name.lowercased()
      }) { stories[i] = generated } else { stories.append(generated) }
      pages[p] = StoryPage(entry.page, stories: stories)
      result[g] = StoryGroup(entry.group, pages: pages)
    }
    let pageOrder = ["Tokens/Color","Tokens/Typography","Tokens/Spacing","Tokens/Radius","Tokens/Effect","Tokens/Control","Tokens/Primitives","Tokens/Variables","Components/Accordion","Components/ActionBar","Components/Autocomplete","Components/Avatar","Components/Badge","Components/Button","Components/Callout","Components/Card","Components/Checkbox","Components/Code","Components/CodeBlock","Components/Collapsible","Components/Combobox","Components/ContextMenu","Components/Dialog","Components/Divider","Components/Drawer","Components/EmptyState","Components/Form","Components/FormField","Components/Icon","Components/IconButton","Components/KeyCap","Components/Link","Components/Menu","Components/Menubar","Components/Meter","Components/NumberField","Components/OptionCard","Components/OtpField","Components/PillTabs","Components/Popover","Components/Preferences","Components/PreviewCard","Components/Progress","Components/Radio","Components/SearchField","Components/SectionLabel","Components/SegmentedControl","Components/Select","Components/ShortcutRecorder","Components/Sidebar","Components/Skeleton","Components/Slider","Components/Spinner","Components/Splitter","Components/StepList","Components/Switch","Components/Table","Components/Tag","Components/TextField","Components/Toast","Components/Toggle","Components/ToggleGroup","Components/Tooltip","Components/Tree"]
    return result.map { group in
      StoryGroup(group.name, pages: group.pages.sorted {
        (pageOrder.firstIndex(of: "\(group.name)/\($0.name)") ?? pageOrder.count) <
        (pageOrder.firstIndex(of: "\(group.name)/\($1.name)") ?? pageOrder.count)
      })
    }
  }
}
/// A number as the shared declaration prints it: no trailing `.0`.
private func sceneText(_ value: Double) -> String {
  value == value.rounded() && abs(value) < 1e15 ? String(Int(value)) : String(value)
}
